action_details.action_postfix:
// No nexus - no filing required
0.0 apportionment.state_tax xdef
apportionment.state_payments apportionment.state_refund_or_owed xdef

// Calculate state additions (customize for Hawaii)
0.0 /additions xdef

// Example: Add back federal interest (not taxable federally but may be taxable to Hawaii)
// additions revenue.federal_bond_interest add /additions xdef

// Example: Add back IRC 199A deduction if state doesn't conform
// additions result.section_199a_deduction add /additions xdef

// Example: Add back bonus depreciation if state decouples
// additions result.bonus_depreciation_total add /additions xdef

additions apportionment.state_additions xdef

// Calculate state subtractions (customize for Hawaii)
0.0 /subtractions xdef

// Example: Subtract municipal bond interest from other states
// subtractions revenue.other_state_municipal_interest add /subtractions xdef

// Example: Subtract state NOL deduction (if different from federal)
// subtractions result.state_nol_deduction add /subtractions xdef

subtractions apportionment.state_subtractions xdef

// Hawaii uses 6.4% flat rate
apportionment.state_taxable_income apportionment.state_tax_rate mul
apportionment.state_tax xdef

// Subtract state credits
apportionment.state_tax apportionment.state_credits sub
0.0 max apportionment.state_tax xdef

// Calculate refund or amount owed
apportionment.state_payments apportionment.state_tax sub
apportionment.state_refund_or_owed xdef
